<?php
require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/auth.php';require_login();
$employeeCount=(int)$pdo->query('SELECT COUNT(*) FROM employees')->fetchColumn();$payrollTotal=(float)$pdo->query('SELECT COALESCE(SUM(net_salary),0) FROM payroll')->fetchColumn();$paid=(float)$pdo->query("SELECT COALESCE(SUM(net_salary),0) FROM payroll WHERE payment_status='Paid'")->fetchColumn();$pending=(float)$pdo->query("SELECT COALESCE(SUM(net_salary),0) FROM payroll WHERE payment_status='Pending'")->fetchColumn();
$employees=$pdo->query('SELECT employee_code,full_name,department,designation,joining_date,basic_salary FROM employees ORDER BY department,full_name')->fetchAll();
$payroll=$pdo->query('SELECT p.pay_month,e.employee_code,e.full_name,e.department,p.basic_salary,p.allowance,p.bonus,p.deduction,p.unpaid_deduction,p.net_salary,p.payment_status FROM payroll p JOIN employees e ON e.id=p.employee_id ORDER BY p.pay_month DESC,e.full_name')->fetchAll();
$page_title='Reports | EIPS';require __DIR__.'/includes/header.php';?>
<div class="page-heading"><div><div class="eyebrow">REPORTS & ANALYTICS</div><h1>Reports</h1><p class="muted">Employee directory and payroll summaries.</p></div><button class="btn primary no-print" onclick="window.print()">Print / Save report</button></div>
<div class="stats-grid"><div class="stat-card"><p>Total employees</p><h2><?=$employeeCount?></h2></div><div class="stat-card"><p>Total net payroll</p><h2><?=money($payrollTotal)?></h2></div><div class="stat-card"><p>Paid salary</p><h2><?=money($paid)?></h2></div><div class="stat-card"><p>Pending salary</p><h2><?=money($pending)?></h2></div></div>
<section class="panel"><div class="panel-heading"><div><h2>Employee report</h2><p class="muted">Employee details and basic salary</p></div></div><div class="table-wrap"><table><thead><tr><th>Code</th><th>Name</th><th>Department</th><th>Designation</th><th>Joining date</th><th>Basic salary</th></tr></thead><tbody><?php foreach($employees as $r):?><tr><td><?=e($r['employee_code'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['department'])?></td><td><?=e($r['designation'])?></td><td><?=e($r['joining_date'])?></td><td><?=money($r['basic_salary'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><div class="panel-heading"><div><h2>Payroll report</h2><p class="muted">Monthly salary component summary</p></div></div><?php if(!$payroll):?><div class="empty-state"><p>No payroll records available.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Month</th><th>Employee</th><th>Basic</th><th>Allowance</th><th>Bonus</th><th>Deductions</th><th>Net pay</th><th>Status</th></tr></thead><tbody><?php foreach($payroll as $r):?><tr><td><?=e($r['pay_month'])?></td><td><?=e($r['full_name'])?></td><td><?=money($r['basic_salary'])?></td><td><?=money($r['allowance'])?></td><td><?=money($r['bonus'])?></td><td><?=money((float)$r['deduction']+(float)$r['unpaid_deduction'])?></td><td><?=money($r['net_salary'])?></td><td><?=e($r['payment_status'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php require __DIR__.'/includes/footer.php';?>
